INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "李茂贞", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“岐王在唐亡后开府置百官”中为开府者。", "biography": null, "status": "draft", "id": "af9a00d1-c748-5b5f-9175-1af19530d83d"}, {"name": "满存", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：满存。", "biography": null, "status": "draft", "id": "d059ac12-f3b5-583e-8f9f-cbf03e28dc9b"}, {"name": "杨行密", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：杨行密。", "biography": null, "status": "draft", "id": "ad75628e-5958-5672-9403-eb349ca77e6e"}, {"name": "田頵", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的田頵，在此段中为击退进攻者。", "biography": null, "status": "draft", "id": "c59b24ec-67c0-5ac6-aaaf-4908d96913b9"}, {"name": "安仁义", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：安仁义。", "biography": null, "status": "draft", "id": "818f8166-7d71-5f56-8c1b-a53a37fca14f"}, {"name": "孙儒", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：孙儒。", "biography": null, "status": "draft", "id": "4426793f-0bd8-5a79-919f-7e3a0ddae520"}, {"name": "高勖", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福元年条所见人物：高勖。", "biography": null, "status": "draft", "id": "8df59026-c4a8-554d-a814-18c5d378e0a7"}, {"name": "李克用", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 908, "description": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "biography": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "status": "draft", "id": "04af206e-fa86-581c-86b9-87a78a8d59a5"}, {"name": "李匡威", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：李匡威。", "biography": null, "status": "draft", "id": "bdc4b069-347f-5d1c-bafc-bbc5e7e2be44"}, {"name": "赫连铎", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：赫连铎。", "biography": null, "status": "draft", "id": "b54a0fc9-ea29-5e0d-9d2a-f8fe5be8cda9"}, {"name": "李君庆", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福元年条所见人物：李君庆。", "biography": null, "status": "draft", "id": "d3ef808b-5bd3-50ab-849a-65b806bccbe2"}, {"name": "杨复恭", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：杨复恭。", "biography": null, "status": "draft", "id": "d84e65f4-4bf5-58ad-a8c6-d69729edbc51"}, {"name": "杨守亮", "aliases": ["訾亮"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：杨守亮。", "biography": null, "status": "draft", "id": "794556be-c340-512f-923f-61f100db55df"}, {"name": "杨守信", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：杨守信。", "biography": null, "status": "draft", "id": "3162cc98-31d1-5f1c-8d13-86cc7912a541"}, {"name": "杨守贞", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：杨守贞。", "biography": null, "status": "draft", "id": "20b5a758-b788-5956-b09f-d976b8538b1e"}, {"name": "杨守忠", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：杨守忠。", "biography": null, "status": "draft", "id": "50f2860b-439a-50ba-9bde-3a2cd10515bc"}, {"name": "李继密", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福元年条所见人物：李继密。", "biography": null, "status": "draft", "id": "27468166-8e95-5cdb-8b71-676673e9d18c"}, {"name": "成汭", "aliases": ["郭禹"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：成汭。", "biography": null, "status": "draft", "id": "c476a6a9-2254-5cdf-b51d-55a7f49d0dd8"}, {"name": "时溥", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的时溥：求援者。", "biography": null, "status": "draft", "id": "075f8bab-c2fc-5a9e-b8b2-a0d12c7ac981"}, {"name": "朱温", "aliases": ["朱全忠", "朱晃", "梁太祖"], "era": "五代十国", "birth_year": null, "death_year": 912, "description": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "biography": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "status": "draft", "id": "0555e455-34d4-54ef-b93e-b0e6425018ab"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "李茂贞克凤州，满存奔兴元", "start_year": 892, "end_year": 892, "time_original": "892年七月己巳", "dynasty": "唐", "description": "李茂贞攻克凤州，感义节度使满存逃奔兴元。", "phases": [], "location_name": "凤州、兴元", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2f7152bd-3b8e-54b8-9c1f-db1f75c3f21e"}, {"title": "李茂贞又取兴洋，表子弟镇之", "start_year": 892, "end_year": 892, "time_original": "892年七月己巳后条；逐次日未载", "dynasty": "唐", "description": "李茂贞又取得兴州、洋州，上表请求由其子弟镇守。", "phases": [], "location_name": "兴州、洋州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6ae58ed0-35b1-5e91-b89e-51baa9ed295e"}, {"title": "杨行密授淮南节度，田頵安仁义授职", "start_year": 892, "end_year": 892, "time_original": "892年八月；具体日未载", "dynasty": "唐", "description": "朝廷任杨行密为淮南节度使、同平章事，以田頵知宣州留后，安仁义为润州刺史。", "phases": [], "location_name": "淮南、宣州、润州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "9d1ac847-21e4-5041-a677-2b7794d4cbd4"}, {"title": "杨行密选孙儒降兵五千组成黑云都", "start_year": 892, "end_year": 892, "time_original": "孙儒败降后；八月条所附；确切编组日未载", "dynasty": "唐", "description": "孙儒降兵多为蔡人，杨行密从中选尤为勇健的五千人，厚给禀赐，以黑衣蒙甲，号黑云都。", "phases": [], "location_name": "淮南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "43edf3b1-9988-542f-9141-741ff02ca362"}, {"title": "黑云都后来先登陷阵的总述", "start_year": null, "end_year": null, "time_original": "编组之后；每战；各次确年日未载", "dynasty": "唐", "description": "《通鉴》总述杨行密后来每逢作战使黑云都先登陷阵，四邻畏惧。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "6dc3bc48-2107-53bb-8350-f35465787cc2"}, {"title": "高勖劝杨行密以邻道贸易、劝农桑足用", "start_year": 892, "end_year": 892, "time_original": "用度不足时；八月条所附；具体日未载", "dynasty": "唐", "description": "杨行密因用度不足，想用茶盐换取居民布帛。掌书记高勖认为兵火后再向民取利恐致离叛，劝以本地所有换邻道所无供军，并任贤守令劝农桑；杨行密听从。田頵称赞贤者之言利远。", "phases": [], "location_name": "淮南、邻道", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ff8cec03-0af6-50e5-8eca-a8f498c7086b"}, {"title": "杨行密容忍从者盗马鞦金饰的轶事", "start_year": null, "end_year": null, "time_original": "尝早出；它日；确年日未载", "dynasty": "唐", "description": "《通鉴》记杨行密一次早出，从者割断马鞦取金，杨行密知而不问，另日仍照常早出；书中说人们佩服其度量。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "5cbd7988-cdd5-5d04-9c02-a8c8e8ec6f6a"}, {"title": "淮南受兵六年、杨行密初至给赐微薄", "start_year": null, "end_year": null, "time_original": "受兵六年；杨行密初至；确切起止未载", "dynasty": "唐", "description": "《通鉴》述淮南受兵六年，士民转徙几尽；杨行密初至，给将吏布帛不过数尺、钱不过数百，以勤俭足用，非公宴未举乐。", "phases": [], "location_name": "淮南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "45391ab9-a101-5655-b3d8-624eac4a95cf"}, {"title": "杨行密招流散、轻徭薄敛后淮南复富", "start_year": null, "end_year": null, "time_original": "未及数年；具体起止未载", "dynasty": "唐", "description": "杨行密招抚流散居民，轻徭薄敛；《通鉴》说不到数年公私富庶，接近承平旧况。", "phases": [], "location_name": "淮南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e9a83097-9ada-5f6c-ad36-cfafe662bda5"}, {"title": "李克用北巡应云州之寇，神堆擒逻骑", "start_year": 892, "end_year": 892, "time_original": "892年八月条；丙申之前", "dynasty": "唐", "description": "李克用北巡至天宁军，闻李匡威与赫连铎率八万兵攻云州，派李君庆在晋阳发兵；李克用潜入新城，伏兵神堆，擒吐谷浑逻骑三百，李匡威等惊惧。", "phases": [], "location_name": "天宁军、新城、神堆、云州、晋阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d4f91b28-c9e4-54a7-b1ba-7b6161d6a792"}, {"title": "李君庆援至，李克用云州大破来军", "start_year": 892, "end_year": 892, "time_original": "892年八月丙申援至；丁酉出击", "dynasty": "唐", "description": "丙申李君庆率大军抵达，李克用进入云州；丁酉李克用出击李匡威等，大破之。", "phases": [], "location_name": "云州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b95739ce-0b55-5c3a-8e15-74389febe41a"}, {"title": "云州来军烧营退走，河东军追至天成", "start_year": 892, "end_year": 892, "time_original": "892年八月己亥", "dynasty": "唐", "description": "己亥，底本所称天威等烧营而退，河东军追至天成军；《通鉴》称斩获不可胜计。", "phases": [], "location_name": "云州、天成军", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "595f2e17-7961-5bab-9c35-f4a28518b8b5"}, {"title": "李茂贞拔兴元，诸杨与满存奔阆州", "start_year": 892, "end_year": 892, "time_original": "892年八月辛丑", "dynasty": "唐", "description": "李茂贞攻下兴元，杨复恭、杨守亮、杨守信、杨守贞、杨守忠、满存逃奔阆州。", "phases": [], "location_name": "兴元、阆州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f3a3c7eb-136a-5b1f-9ebd-2d2040753827"}, {"title": "李茂贞表李继密权知兴元府事", "start_year": 892, "end_year": 892, "time_original": "892年八月辛丑条", "dynasty": "唐", "description": "李茂贞上表以李继密权知兴元府事，《通鉴》称继密为其子。", "phases": [], "location_name": "兴元", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7db37a53-db4a-5bab-ba0c-46b1a9ffce7e"}, {"title": "成汭加同平章事", "start_year": 892, "end_year": 892, "time_original": "892年九月", "dynasty": "唐", "description": "荆南节度使成汭加同平章事。", "phases": [], "location_name": "荆南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2f57cb99-8521-5849-8458-64792aa44ed2"}, {"title": "时溥复授感化，朱全忠请追回新命", "start_year": 892, "end_year": 892, "time_original": "892年冬十月", "dynasty": "唐", "description": "时溥迫使监军奏称将士要留他，朝廷复以时溥为侍中、感化节度使。朱全忠奏请追回新命，朝廷诏谕劝解。", "phases": [], "location_name": "感化、徐州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f1461460-ceeb-5bcc-bc6b-0ddf2699e5cc"}]'::jsonb)
